module mux2_gate (input a, input b, input sel, output y);
  wire nsel, t0, t1;
  not g0 (nsel, sel);
  and g1 (t0, a, nsel);
  and g2 (t1, b, sel);
  or  g3 (y, t0, t1);
endmodule

module mux2_df (input a, input b, input sel, output y);
  assign y = sel ? b : a;
endmodule

module mux2_beh (input a, input b, input sel, output reg y);
  always @(*)
    if (sel) y = b;
    else     y = a;
endmodule

module counter4 (input clk, input reset, output reg [3:0] count);
  always @(posedge clk or posedge reset)
    if (reset) count &lt;= 4'd0;
    else       count &lt;= count + 4'd1;
endmodule

`timescale 1ns/1ns
module tb_counter4;
  reg clk = 0, reset = 1;
  wire [3:0] count;
  counter4 uut (.clk(clk), .reset(reset), .count(count));
  always #5 clk = ~clk;
  initial begin
    $dumpfile("counter.vcd"); $dumpvars(0, tb_counter4);
    $monitor("t=%0t reset=%b count=%0d", $time, reset, count);
    #12 reset = 0;
    #170 $finish;
  end
endmodule

module fa_gate (input a, input b, input cin, output sum, output cout);
  wire s1, c1, c2;
  xor g1 (s1, a, b);
  xor g2 (sum, s1, cin);
  and g3 (c1, a, b);
  and g4 (c2, s1, cin);
  or  g5 (cout, c1, c2);
endmodule

module fa_df (input a, input b, input cin, output sum, output cout);
  assign sum  = a ^ b ^ cin;
  assign cout = (a &amp; b) | (b &amp; cin) | (a &amp; cin);
endmodule

`timescale 1ns/1ns
module tb_fa;
  reg a, b, cin;
  wire s_g, c_g, s_d, c_d;
  integer i, errors = 0;
  fa_gate ug (.a(a), .b(b), .cin(cin), .sum(s_g), .cout(c_g));
  fa_df   ud (.a(a), .b(b), .cin(cin), .sum(s_d), .cout(c_d));
  initial begin
    for (i = 0; i &lt; 8; i = i + 1) begin
      {a, b, cin} = i;
      #10;
      if ({c_g, s_g} !== a + b + cin || {c_d, s_d} !== a + b + cin)
        errors = errors + 1;
      $display("%b%b%b  gate %b%b  dataflow %b%b", a, b, cin, c_g, s_g, c_d, s_d);
    end
    if (errors == 0) $display("PASS: 8 of 8"); else $display("FAIL: %0d", errors);
    $finish;
  end
endmodule
